/* =========================================================
   Always Encrypted: llaves de las columnas Users.first_name / Users.last_name
   ---------------------------------------------------------
   YA APLICADO en Azure (1 de octubre de 2026): la CMK con T-SQL y la CEK con SSMS.
   Este archivo documenta el estado de la base; no hace falta volver a ejecutarlo.

   - CMK_Orders: solo una referencia a la llave RSA 3072 "orders-pii-kek" de dp3-kv-crypto.
     Sin ENCLAVE_COMPUTATIONS: la llave no se habilita para enclaves.
   - CEK_UsersNames: llave AES-256 generada por SSMS. ENCRYPTED_VALUE es la llave **cifrada**
     (RSA-OAEP) y firmada con la CMK; sin acceso a Key Vault no sirve de nada.
   - Una CEK nueva NO se puede escribir a mano: el valor lo genera SSMS o PowerShell (SqlServer).
   ========================================================= */

CREATE COLUMN MASTER KEY CMK_Orders
WITH (
    KEY_STORE_PROVIDER_NAME = N'AZURE_KEY_VAULT',
    KEY_PATH = N'https://dp3-kv-crypto.vault.azure.net/keys/orders-pii-kek/c340ffe1ece7412f85ed5524466d1582'
);

CREATE COLUMN ENCRYPTION KEY CEK_UsersNames
WITH VALUES (
    COLUMN_MASTER_KEY = CMK_Orders,
    ALGORITHM = 'RSA_OAEP',
    ENCRYPTED_VALUE = 
);

-- Permisos de la app para leer los metadatos de las llaves (en Azure SQL no vienen por defecto)
GRANT VIEW ANY COLUMN MASTER KEY DEFINITION TO [dp3-appservice-orders];
GRANT VIEW ANY COLUMN ENCRYPTION KEY DEFINITION TO [dp3-appservice-orders];
